var picker = new ArcDatePicker
{
    Label = "预约日期",
    Width = 280,
    Placeholder = "只能选工作日",
    MinDate = DateTime.Today,
    MaxDate = DateTime.Today.AddDays(45),
    DisabledDates = day => day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday,
    ShowToday = true
};

picker.SelectedDateChanged += (_, date) =>
    statusText.Text = date is null ? "尚未选择日期" : date.Value.ToString("yyyy-MM-dd");
